package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.workflow.WorkflowProtocol.Dispatch;
import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;
/** N04-only historical invocation and owned-process facts, never N02 aliases. */
public final class TaskSectionWriterLifecycleFacts {
    private final JdbcTemplate db;private final TaskSectionWriterDispatchJournal dispatches;private final TaskSectionWriterInvocationRecords invocations;private final TaskSectionWriterSupervisor supervisor;private final TaskSectionWriterSchema json;private final TaskRunSectionWriterProtocolBinding protocols;
    public TaskSectionWriterLifecycleFacts(DataSource data,TaskSectionWriterDispatchJournal dispatches,TaskSectionWriterInvocationRecords invocations,TaskSectionWriterSupervisor supervisor,TaskSectionWriterSchema json,TaskRunSectionWriterProtocolBinding protocols){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.dispatches=dispatches;this.invocations=invocations;this.supervisor=supervisor;this.json=json;this.protocols=protocols;}
    boolean writer(TaskRunLifecycleAuthority.Proof p,String step){p.admission().controlProof().requireActive();var rows=db.queryForList("SELECT node_kind FROM runtime_node_definition WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",p.reference().tenantId(),p.reference().projectId(),p.reference().runId(),step);return !rows.isEmpty()&&"N04".equals(text(one(rows),"node_kind"));}
    FormalInvocationBinding invocation(TaskRunLifecycleAuthority.Proof p,String invocation)throws Exception{p.require(p.operation());protocols.requireAccepted(p.admission(),p.reference().runId()).requireUnchanged();var b=invocations.byInvocation(p.reference().tenantId(),invocation);same(p.reference().runId(),b.run());same(p.reference().projectId(),b.project());same(p.admission().actorId(),b.actor());var original=dispatches.forLifecycle(p,b.step(),Long.parseLong(b.generation()));same(b.inputHash(),original.dispatch().inputSha256());same(b.session(),original.envelope().required("session_id").textValue());same(original.launch().required("binding"),b.original().dependencies().required("host_binding"));original.requireUnchanged();return b;}
    Dispatch dispatch(TaskRunLifecycleAuthority.Proof p,String step,long generation)throws Exception{return dispatches.forLifecycle(p,step,generation).dispatch();}
    JsonNode session(TaskRunLifecycleAuthority.Proof p,Map<String,Object> row)throws Exception{
        p.require(p.operation());protocols.requireAccepted(p.admission(),p.reference().runId()).requireUnchanged();var r=p.reference();String step=text(row,"step_id"),id=text(row,"session_id");var original=dispatches.forLifecycle(p,step,Long.parseLong(number(row,"lease_generation")));var d=original.dispatch();same(d.actionId(),text(row,"action_id"));same(d.inputSha256(),text(row,"input_sha256"));same(d.stepEnvelopeSha256(),text(row,"envelope_sha256"));
        var start=json.read(text(row,"canonical_start"));same(json.hash(start),text(row,"start_sha256"));same(id,start.required("session_id").textValue());same("N04",start.required("node_kind").textValue());same("TASK",start.required("purpose").textValue());var launch=original.launch();same(launch.required("binding"),start.required("binding"));same(launch.required("deployment_sha256"),start.required("deployment_sha256"));var prepare=start.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)prepare).put("state","PREPARE").remove(List.of("isolation_receipt_id","supervision_sha256"));same(launch,prepare);
        same(start,json.read((String)one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND action='task.section_writer.session.opened' AND request_id=? AND result='SUCCESS' LIMIT 2 FOR UPDATE",(rs,n)->rs.getString(1),r.tenantId(),r.projectId(),p.admission().actorId(),id))));same(start,json.read((String)one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND event_type='task.section_writer.session.opened' LIMIT 2 FOR UPDATE",(rs,n)->rs.getString(1),r.tenantId(),id))));
        var result=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("session_id",id).put("step_id",step).put("lease_generation",d.leaseGeneration()).put("start_sha256",json.hash(start));var closed=supervisor.lifecycleClosure(original);if(closed.isEmpty())result.putNull("closed");else{result.set("closed",closed.get());result.put("closed_sha256",json.hash(closed.get()));}original.requireUnchanged();return result;
    }
}
